        /// <summary>
        /// Validates every generated table under the production catalog rules and returns the immutable
        /// catalog, or the exact structured rejections (P-009). Nothing is exposed on rejection.
        /// </summary>
        public static CatalogBuildResult BuildCatalog()
        {
            FactoryRegistration[] groupRegistrations = GroupCatalogRegistrations();
            FactoryRegistration[] all = new FactoryRegistration[groupRegistrations.Length + SchemaRegistrations.Length];
            Array.Copy(groupRegistrations, 0, all, 0, groupRegistrations.Length);

            for (int i = 0; i < SchemaRegistrations.Length; i++)
            {
                SchemaRegistration registration = SchemaRegistrations[i];
                all[groupRegistrations.Length + i] = new FactoryRegistration(
                    registration.Serializer,
                    FactoryKind.Serializer,
                    registration.OwnerPackageId,
                    registration.Schema.Id.Value,
                    registration.Schema.Version);
            }

            return ImmutableCatalog.Build(all, SchemaRegistrations, SupportedFeatureIds, Serializers);
        }

        /// <summary>Every group's catalog registrations concatenated in declaration order.</summary>
        private static FactoryRegistration[] GroupCatalogRegistrations()
        {
            return Array.Empty<FactoryRegistration>();
        }

        /// <summary>
        /// Builds the catalog and asserts that its fingerprint equals the value emitted into this file, so a
        /// stale generated file cannot describe a catalog whose declarations changed (P-028).
        /// </summary>
        public static CatalogBuildResult BuildVerifiedCatalog(out ContentHash observedFingerprint)
        {
            CatalogBuildResult result = BuildCatalog();
            observedFingerprint = result.Catalog == null ? ContentHash.Empty : result.Catalog.Fingerprint;
            return result;
        }

        /// <summary>
        /// Fingerprint the generated declarations must produce. A test compares this literal against a
        /// freshly built catalog so an unnoticed declaration change fails instead of being ignored.
        /// </summary>
        public static bool FingerprintMatchesGeneratedCatalog(out ContentHash observed)
        {
            CatalogBuildResult result = BuildVerifiedCatalog(out observed);
            return result.Catalog != null && string.Equals(observed.ToHex(), CatalogFingerprint, StringComparison.Ordinal);
        }

